import 'package:uuid/uuid.dart';import '../models/commitment.dart';import '../models/employee.dart';import 'gemini_service.dart';import 'storage_service.dart';import 'notification_service.dart';
class AssistantController {static Future<String> handle(String text)async{final key=StorageService.apiKey;if(key.isEmpty)return '⚠️ ضع مفتاح Gemini من الإعدادات أولاً.';final d=await GeminiService(key).parse(text);final intent=d['intent']??'other';if(intent=='add_employee'){final e=Employee(id:const Uuid().v4(),name:d['employee_name']??d['person']??'موظف',role:d['employee_role']??'عامل',startDate:DateTime.tryParse(d['start_date']??'')??DateTime.now(),salaryMonthly:(d['salary'] as num?)?.toDouble()??0);await StorageService.saveEmployee(e);return '✅ سجلت الموظف ${e.name}، المرتب ${e.salaryMonthly.toStringAsFixed(0)} جنيه.';}if(intent=='add_advance'){final name=d['person']??d['employee_name']??'';final e=StorageService.findEmployee(name);if(e==null)return '❓ لم أجد موظف باسم $name.';e.advances.add(Advance(id:const Uuid().v4(),amount:(d['amount'] as num?)?.toDouble()??0,date:DateTime.now(),note:text));await StorageService.saveEmployee(e);return '✅ سجلت السلفة لـ ${e.name}.';}if(intent=='mark_attendance'){final e=StorageService.findEmployee(d['person']??'');if(e==null)return '❓ لم أجد الموظف.';final day=DateTime.now().toIso8601String().substring(0,10);if(!e.attendance.contains(day))e.attendance.add(day);await StorageService.saveEmployee(e);return '✅ تم تسجيل حضور ${e.name} اليوم.';}if(intent=='create_commitment'){final due=DateTime.tryParse(d['due_date']??'')??DateTime.now().add(const Duration(days:1));final rem=DateTime.tryParse((d['remind_at']??'').replaceFirst(' ','T'))??due.subtract(const Duration(hours:1));final c=Commitment(id:const Uuid().v4(),textOriginal:d['text_original']??text,person:d['person']??'عام',type:d['type']??'task',amount:(d['amount'] as num?)?.toDouble(),dueDate:due,remindAt:rem,followUpRule:d['follow_up_rule']??'');await StorageService.saveCommitment(c);await NotificationService.schedule(c);return 'تمام ✅ سجلت ${c.person}${c.amount==null?'':' - ${c.amount!.toStringAsFixed(0)} جنيه'}، والتذكير ${c.remindAt.toString().substring(0,16)}.';}return 'لم أفهم العملية المطلوبة بوضوح.';}}
